CREATE TRIGGER `discharge_document_source` BEFORE INSERT ON `discharge_documents` FOR EACH ROW
trg: BEGIN
  DECLARE l_key VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE a_id VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE a_banned TINYINT;
  DECLARE a_role VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE e_id UUID;
  DECLARE e_status VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE e_bill_revision INT;
  DECLARE departure_id UUID;
  DECLARE prev_id UUID;
  DECLARE prev_version INT;
  IF NEW.schema_version = 1 THEN
    SELECT id, banned, role INTO a_id, a_banned, a_role FROM staff_user WHERE id = NEW.created_by LOCK IN SHARE MODE;
    IF a_id IS NULL OR a_banned OR a_role NOT IN ('ADMIN','BILLING') THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Current final-copy delivery staff required';
    END IF;
    SELECT id, status, bill_revision INTO e_id, e_status, e_bill_revision FROM admissions WHERE id = NEW.admission_id FOR UPDATE;
    IF NOT (e_status <=> 'DISCHARGED')
       OR NOT (CAST(JSON_VALUE(NEW.snapshot, '$.admission.id') AS UUID) <=> e_id)
       OR NOT (CAST(JSON_VALUE(NEW.snapshot, '$.documentId') AS UUID) <=> NEW.id)
       OR NOT (CAST(JSON_VALUE(NEW.snapshot, '$.version') AS SIGNED) <=> NEW.version)
       OR NOT ((JSON_VALUE(NEW.snapshot, '$.sourceHash') COLLATE utf8mb4_nopad_bin) <=> NEW.source_hash)
       OR NOT (CAST(JSON_VALUE(NEW.snapshot, '$.money.bill.revision') AS SIGNED) <=> e_bill_revision)
       OR NOT (CAST(LEFT(REPLACE(REPLACE(JSON_VALUE(NEW.snapshot, '$.createdAt'), 'T', ' '), 'Z', ''), 26) AS DATETIME(6)) <=> NEW.created_at) THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Coherent actual departure document source required';
    END IF;
    SELECT id INTO departure_id FROM departures WHERE admission_id = e_id LIMIT 1;
    IF departure_id IS NOT NULL THEN
      IF JSON_VALUE(NEW.snapshot, '$.departure.kind') <> 'ORDINARY' OR NOT (CAST(JSON_VALUE(NEW.snapshot, '$.departure.record.id') AS UUID) <=> departure_id) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Original ordinary departure source required';
      END IF;
    ELSE
      SELECT id INTO departure_id FROM exceptional_departures WHERE admission_id = e_id LIMIT 1;
      IF departure_id IS NULL OR JSON_VALUE(NEW.snapshot, '$.departure.kind') <> 'EXCEPTIONAL' OR NOT (CAST(JSON_VALUE(NEW.snapshot, '$.departure.record.id') AS UUID) <=> departure_id) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Original exceptional departure source required';
      END IF;
    END IF;
    SELECT id, version INTO prev_id, prev_version FROM discharge_documents WHERE admission_id = e_id ORDER BY version DESC LIMIT 1;
    IF NEW.version <> COALESCE(prev_version, 0) + 1 OR NOT (NEW.replaces_document_id <=> prev_id) THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Sequential immutable document predecessor required';
    END IF;
  END IF;
END
-- END TRIGGER

