    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Refund actual time outside receipt history';
  END IF;
  IF NEW.amount_paise + COALESCE((SELECT SUM(amount_paise) FROM receipt_refunds WHERE receipt_id = r_id), 0) > r_amount_paise THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Refund exceeds original receipt';
  END IF;
