    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Cancel allocated deposit before refund';
  END IF;
END
-- END TRIGGER

-- TRIGGER name=clearance_source_guard table=clearance_seals timing=BEFORE event=INSERT pg_name=clearance_source_guard
DROP TRIGGER IF EXISTS `clearance_source_guard`;
CREATE TRIGGER `clearance_source_guard` BEFORE INSERT ON `clearance_seals` FOR EACH ROW
trg: BEGIN
  DECLARE e_id UUID;
  DECLARE s_id UUID;
  DECLARE s_admission_id UUID;
  DECLARE s_gate VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  SELECT id INTO e_id FROM admissions WHERE id = NEW.admission_id FOR UPDATE;
  IF NOT EXISTS(SELECT 1 FROM staff_user WHERE id = NEW.signed_by AND role = NEW.role AND COALESCE(banned, 0) = 0) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Current actual seal role required';
  END IF;
  IF NEW.gate <> 'DOCTOR' THEN
    SELECT id, admission_id, gate INTO s_id, s_admission_id, s_gate FROM clearance_seals WHERE id = NEW.predecessor_id;
    IF NOT (s_admission_id <=> e_id) OR NOT (NULLIF(FIELD(s_gate, 'DOCTOR', 'PHARMACY', 'NURSING', 'BILLING'), 0) <=> NULLIF(FIELD(NEW.gate, 'DOCTOR', 'PHARMACY', 'NURSING', 'BILLING'), 0) - 1) OR EXISTS(SELECT 1 FROM clearance_invalidations WHERE seal_id = s_id) THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Current same-episode predecessor required';
    END IF;
  END IF;
END
-- END TRIGGER

