-- TRIGGER name=effective_attendance_guard_administrative_shift_ends table=administrative_shift_ends timing=BEFORE event=INSERT pg_name=effective_attendance_guard
DROP TRIGGER IF EXISTS `effective_attendance_guard_administrative_shift_ends`;
CREATE TRIGGER `effective_attendance_guard_administrative_shift_ends` BEFORE INSERT ON `administrative_shift_ends` FOR EACH ROW
trg: BEGIN
  DECLARE n_id UUID;
  DECLARE n_admission_id UUID;
  DECLARE n_nurse_id VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE n_started_at DATETIME(6);
  DECLARE e_id UUID;
  DECLARE moment DATETIME(6);
  DECLARE x_admission_id UUID;
  DECLARE x_type VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE x_disposition VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE x_source_id UUID;
  SELECT id, admission_id, nurse_id, started_at INTO n_id, n_admission_id, n_nurse_id, n_started_at FROM nursing_shifts WHERE id = NEW.shift_id;
  IF n_id IS NULL THEN
    LEAVE trg;
  END IF;
  SELECT id INTO e_id FROM admissions WHERE id = n_admission_id FOR UPDATE;
  SET moment = NEW.ended_at;
  IF EXISTS(SELECT 1 FROM effective_shift_ends WHERE shift_id = n_id) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Attendance already has a retained factual end';
  END IF;
  SELECT admission_id, type, disposition, source_id INTO x_admission_id, x_type, x_disposition, x_source_id FROM admin_exceptions WHERE id = NEW.exception_id;
    IF NOT (x_admission_id <=> e_id) OR x_type <> 'UNAVAILABLE_APPROVER' OR x_disposition <> 'CLOSE_ATTENDANCE' OR NOT (x_source_id <=> n_id) OR NOT (NEW.admission_id <=> e_id) OR NOT EXISTS(SELECT 1 FROM staff_user WHERE id = NEW.signed_by AND role = 'ADMIN' AND COALESCE(banned, 0) = 0) THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Original shift and actual Admin exception authority required';
    END IF;
  IF EXISTS(SELECT 1 FROM (
      SELECT actual_at AS t FROM medication_administrations WHERE shift_id = n_id
      UNION ALL SELECT observed_at FROM nursing_observations WHERE shift_id = n_id
      UNION ALL SELECT used_at FROM nursing_consumables WHERE shift_id = n_id
      UNION ALL SELECT transferred_at FROM admission_transfers WHERE shift_id = n_id
      UNION ALL SELECT vacated_at FROM effective_vacation_facts WHERE shift_id = n_id
      UNION ALL SELECT actual_at FROM exception_evidence WHERE shift_id = n_id
    ) facts WHERE t > moment) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Attendance cannot end before actual care or physical handover';
  END IF;
  IF moment <= n_started_at OR EXISTS(SELECT 1 FROM departures WHERE admission_id = e_id AND departed_at < moment) OR EXISTS(SELECT 1 FROM exceptional_departures WHERE admission_id = e_id AND departed_at < moment) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Attendance end outside actual episode';
  END IF;
  IF moment > UTC_TIMESTAMP(6) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Actual attendance evidence cannot be in future';
  END IF;
END
-- END TRIGGER

