-- TRIGGER name=effective_consumable_source table=nursing_consumables timing=BEFORE event=INSERT pg_name=effective_consumable_source
DROP TRIGGER IF EXISTS `effective_consumable_source`;
CREATE TRIGGER `effective_consumable_source` BEFORE INSERT ON `nursing_consumables` FOR EACH ROW
trg: BEGIN
  DECLARE e_id UUID;
  SELECT id INTO e_id FROM admissions WHERE id = NEW.admission_id FOR UPDATE;
  IF NOT EXISTS(SELECT 1 FROM effective_room_stays s WHERE s.id = NEW.stay_id AND s.admission_id = NEW.admission_id AND s.bed_id = NEW.bed_id AND NEW.used_at >= s.started_at AND (s.ended_at IS NULL OR NEW.used_at < s.ended_at)) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Consumable must retain its actual effective physical source unit';
  END IF;
END
-- END TRIGGER

-- TRIGGER name=exception_attendance_end table=nursing_shift_ends timing=BEFORE event=INSERT pg_name=exception_attendance_end
DROP TRIGGER IF EXISTS `exception_attendance_end`;
CREATE TRIGGER `exception_attendance_end` BEFORE INSERT ON `nursing_shift_ends` FOR EACH ROW
trg: BEGIN
  DECLARE episode UUID;
  DECLARE e_id UUID;
  SELECT admission_id INTO episode FROM nursing_shifts WHERE id = NEW.shift_id;
  SELECT id INTO e_id FROM admissions WHERE id = episode FOR UPDATE;
  IF EXISTS(SELECT 1 FROM exception_evidence WHERE shift_id = NEW.shift_id AND actual_at > NEW.ended_at) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Attendance cannot end before witnessed physical exception evidence';
  END IF;
END
-- END TRIGGER

-- TRIGGER name=exception_evidence_source table=exception_evidence timing=BEFORE event=INSERT pg_name=exception_evidence_source
DROP TRIGGER IF EXISTS `exception_evidence_source`;
CREATE TRIGGER `exception_evidence_source` BEFORE INSERT ON `exception_evidence` FOR EACH ROW
trg: BEGIN
  DECLARE e_id UUID;
  DECLARE e_status VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE e_admitted_at DATETIME(6);
  DECLARE e_admitting_doctor_id VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE n_id UUID;
  DECLARE n_admission_id UUID;
  DECLARE n_nurse_id VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE n_started_at DATETIME(6);
  SELECT id, status, admitted_at, admitting_doctor_id INTO e_id, e_status, e_admitted_at, e_admitting_doctor_id FROM admissions WHERE id = NEW.admission_id FOR UPDATE;
  IF (e_status <> 'ADMITTED' AND NOT (e_status = 'DISCHARGED' AND NEW.kind IN ('ROOM_CUTOFF','PROFESSIONAL_REVIEW'))) OR NEW.actual_at < e_admitted_at OR NEW.actual_at > UTC_TIMESTAMP(6) OR NEW.signed_at < NEW.actual_at OR NOT EXISTS(SELECT 1 FROM staff_user WHERE id = NEW.signed_by AND role = NEW.role AND NOT banned) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Current professional evidence with factual episode time required';
  END IF;
  IF NEW.kind = 'PROFESSIONAL_REVIEW' AND NOT EXISTS(SELECT 1 FROM admin_exceptions x JOIN exceptional_departures d ON d.id = x.source_id WHERE x.id = NEW.exception_id AND x.admission_id = e_id AND x.type = 'POST_DISCHARGE_CORRECTION' AND x.disposition = 'AMEND' AND x.correction_kind = 'DISPOSITION_REVIEW' AND x.source_id = NEW.source_id AND d.admission_id = e_id) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Professional follow-up requires specific retained departure authority';
  END IF;
  IF NEW.kind = 'ROOM_CUTOFF' AND NOT EXISTS(SELECT 1 FROM admin_exceptions x WHERE x.id = NEW.exception_id AND x.admission_id = e_id AND x.type = 'ROOM_CUTOFF_CORRECTION' AND x.disposition = 'AMEND' AND x.source_id = NEW.source_id) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Cutoff witness must bind retained original authority';
  END IF;
  IF NEW.role = 'DOCTOR' AND e_admitting_doctor_id <> NEW.signed_by THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Assigned Doctor evidence required';
  END IF;
  IF NEW.role = 'NURSE' THEN
    SELECT id, admission_id, nurse_id, started_at INTO n_id, n_admission_id, n_nurse_id, n_started_at FROM nursing_shifts WHERE id = NEW.shift_id;
    IF NOT (n_admission_id <=> e_id) OR NOT (n_nurse_id <=> NEW.signed_by) OR NEW.actual_at < n_started_at OR EXISTS(SELECT 1 FROM effective_shift_ends WHERE shift_id = n_id AND ended_at < NEW.actual_at) OR NOT EXISTS(SELECT 1 FROM nurse_assignments a WHERE a.admission_id = e_id AND a.nurse_id = NEW.signed_by AND NOT EXISTS(SELECT 1 FROM nurse_assignment_revocations r WHERE r.assignment_id = a.id)) THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Current assigned Nurse and actual attendance required';
    END IF;
  END IF;
  IF NEW.vacated_at IS NOT NULL AND (NEW.vacated_at < e_admitted_at OR NEW.vacated_at > NEW.actual_at) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Physical vacancy must precede hospital exit';
  END IF;
END
-- END TRIGGER

-- TRIGGER name=exception_followups_source table=exception_followups timing=BEFORE event=INSERT pg_name=exception_followups_source
DROP TRIGGER IF EXISTS `exception_followups_source`;
CREATE TRIGGER `exception_followups_source` BEFORE INSERT ON `exception_followups` FOR EACH ROW
trg: BEGIN
  DECLARE e_id UUID;
  DECLARE x_id UUID;
  DECLARE x_admission_id UUID;
  DECLARE x_follow_up_owner_id VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE staff_role VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE current_owner VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  SELECT id INTO e_id FROM admissions WHERE id = NEW.admission_id FOR UPDATE;
  SELECT id, admission_id, follow_up_owner_id INTO x_id, x_admission_id, x_follow_up_owner_id FROM admin_exceptions WHERE id = NEW.exception_id;
  SELECT role INTO staff_role FROM staff_user WHERE id = NEW.signed_by AND COALESCE(banned, 0) = 0;
  SELECT owner_id INTO current_owner FROM exception_followups WHERE exception_id = x_id ORDER BY signed_at DESC LIMIT 1;
  SET current_owner = COALESCE(current_owner, x_follow_up_owner_id);
  IF NOT (x_admission_id <=> NEW.admission_id) OR staff_role IS NULL OR (staff_role <> 'ADMIN' AND (NEW.signed_by <> current_owner OR NEW.owner_id <> current_owner)) OR NOT EXISTS(SELECT 1 FROM staff_user WHERE id = NEW.owner_id AND COALESCE(banned, 0) = 0) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Current accountable owner or Admin must record follow-up';
  END IF;
END
-- END TRIGGER

-- TRIGGER name=exceptional_departure_source table=exceptional_departures timing=BEFORE event=INSERT pg_name=exceptional_departure_source
DROP TRIGGER IF EXISTS `exceptional_departure_source`;
CREATE TRIGGER `exceptional_departure_source` BEFORE INSERT ON `exceptional_departures` FOR EACH ROW
trg: BEGIN
  DECLARE e_id UUID;
  DECLARE e_status VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE a_admission_id UUID;
  DECLARE a_disposition VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE a_evidence_ids LONGTEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;
  DECLARE p_id UUID;
  DECLARE p_admission_id UUID;
  DECLARE p_kind VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE p_actual_at DATETIME(6);
  DECLARE p_vacated_at DATETIME(6);
  DECLARE s_admission_id UUID;
  DECLARE s_ended_at DATETIME(6);
  SELECT id, status INTO e_id, e_status FROM admissions WHERE id = NEW.admission_id FOR UPDATE;
  SELECT admission_id, disposition, evidence_ids INTO a_admission_id, a_disposition, a_evidence_ids FROM admin_exceptions WHERE id = NEW.exception_id;
  SELECT id, admission_id, kind, actual_at, vacated_at INTO p_id, p_admission_id, p_kind, p_actual_at, p_vacated_at FROM exception_evidence WHERE id = NEW.physical_evidence_id;
  SELECT admission_id, ended_at INTO s_admission_id, s_ended_at FROM effective_room_stays WHERE id = NEW.stay_id LIMIT 1;
  IF e_status <> 'ADMITTED' OR NOT (a_admission_id <=> e_id) OR a_disposition <> 'EXCEPTIONAL_EXIT' OR NOT (p_admission_id <=> e_id) OR p_kind <> 'PHYSICAL_EXIT' OR NOT (p_actual_at <=> NEW.departed_at) OR NOT (s_admission_id <=> e_id) OR NOT (s_ended_at <=> p_vacated_at) OR NOT EXISTS(SELECT 1 FROM staff_user WHERE id = NEW.signed_by AND role = 'ADMIN' AND NOT banned) OR EXISTS(SELECT 1 FROM departures WHERE admission_id = e_id) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Actual source-linked exceptional departure required';
  END IF;
  IF NOT JSON_CONTAINS(a_evidence_ids, JSON_QUOTE(CAST(p_id AS CHAR))) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Actual departure witness must be included in authority';
  END IF;
  IF EXISTS(SELECT 1 FROM (
      SELECT actual_at AS t FROM medication_administrations WHERE admission_id = e_id
      UNION ALL SELECT observed_at FROM nursing_observations WHERE admission_id = e_id
      UNION ALL SELECT used_at FROM nursing_consumables WHERE admission_id = e_id
      UNION ALL SELECT transferred_at FROM admission_transfers WHERE admission_id = e_id
      UNION ALL SELECT n.ended_at FROM effective_shift_ends n JOIN nursing_shifts h ON h.id = n.shift_id WHERE h.admission_id = e_id
    ) facts WHERE t > NEW.departed_at) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Recorded actual care or attendance continues after claimed departure';
  END IF;
END
-- END TRIGGER

-- TRIGGER name=actual_doctor_exit_chronology table=exception_evidence timing=BEFORE event=INSERT pg_name=actual_doctor_exit_chronology
DROP TRIGGER IF EXISTS `actual_doctor_exit_chronology`;
CREATE TRIGGER `actual_doctor_exit_chronology` BEFORE INSERT ON `exception_evidence` FOR EACH ROW
trg: BEGIN
  DECLARE e_id UUID;
  SELECT id INTO e_id FROM admissions WHERE id = NEW.admission_id FOR UPDATE;
  IF NEW.role = 'DOCTOR' AND NEW.kind IN ('DEATH','EXTERNAL_TRANSFER','AGAINST_ADVICE','PLANNED_EXIT') AND EXISTS(SELECT 1 FROM (SELECT departed_at FROM departures WHERE admission_id = e_id UNION ALL SELECT departed_at FROM exceptional_departures WHERE admission_id = e_id) d WHERE d.departed_at < NEW.actual_at) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Actual professional disposition cannot occur after actual hospital exit';
  END IF;
END
-- END TRIGGER

-- TRIGGER name=planned_exception_instruction table=admin_exceptions timing=BEFORE event=INSERT pg_name=planned_exception_instruction
DROP TRIGGER IF EXISTS `planned_exception_instruction`;
CREATE TRIGGER `planned_exception_instruction` BEFORE INSERT ON `admin_exceptions` FOR EACH ROW
trg: BEGIN
  DECLARE e_id UUID;
  SELECT id INTO e_id FROM admissions WHERE id = NEW.admission_id FOR UPDATE;
  IF NEW.type IN ('CREDIT','INSURANCE_DELAY','INSURANCE_DENIAL') AND NEW.disposition = 'EXCEPTIONAL_EXIT' THEN
    SET @ignored = assert_planned_exit_instruction(e_id, NEW.evidence_ids);
  END IF;
END
-- END TRIGGER

-- TRIGGER name=selected_doctor_exit_chronology table=exceptional_departures timing=BEFORE event=INSERT pg_name=selected_doctor_exit_chronology
DROP TRIGGER IF EXISTS `selected_doctor_exit_chronology`;
CREATE TRIGGER `selected_doctor_exit_chronology` BEFORE INSERT ON `exceptional_departures` FOR EACH ROW
trg: BEGIN
  DECLARE e_id UUID;
  DECLARE a_type VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE a_evidence_ids LONGTEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;
  DECLARE required_kind VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  SELECT id INTO e_id FROM admissions WHERE id = NEW.admission_id FOR UPDATE;
  SELECT type, evidence_ids INTO a_type, a_evidence_ids FROM admin_exceptions WHERE id = NEW.exception_id;
  SET required_kind = CASE WHEN a_type IN ('DEATH','EXTERNAL_TRANSFER','AGAINST_ADVICE') THEN a_type WHEN a_type IN ('CREDIT','INSURANCE_DELAY','INSURANCE_DENIAL') THEN 'PLANNED_EXIT' END;
  IF required_kind IS NOT NULL AND (NOT EXISTS(SELECT 1 FROM exception_evidence p WHERE p.admission_id = e_id AND p.role = 'DOCTOR' AND p.kind = required_kind AND JSON_CONTAINS(a_evidence_ids, JSON_QUOTE(CAST(p.id AS CHAR))) AND p.actual_at <= NEW.departed_at)
     OR EXISTS(SELECT 1 FROM exception_evidence p WHERE p.admission_id = e_id AND p.role = 'DOCTOR' AND p.kind = required_kind AND JSON_CONTAINS(a_evidence_ids, JSON_QUOTE(CAST(p.id AS CHAR))) AND p.actual_at > NEW.departed_at)) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Selected actual Doctor disposition cannot follow the witnessed hospital exit';
  END IF;
  IF required_kind = 'PLANNED_EXIT' THEN
    SET @ignored = assert_planned_exit_instruction(e_id, a_evidence_ids);
  END IF;
END
-- END TRIGGER

-- TRIGGER name=final_charge_source table=charges timing=BEFORE event=INSERT pg_name=final_charge_source
DROP TRIGGER IF EXISTS `final_charge_source`;
CREATE TRIGGER `final_charge_source` BEFORE INSERT ON `charges` FOR EACH ROW
trg: BEGIN
  DECLARE e_id UUID;
  DECLARE e_status VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE e_bill_revision INT;
  DECLARE e_hospital_id UUID;
  DECLARE e_admitting_doctor_id VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE staff_role VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE a_admission_id UUID;
  DECLARE a_type VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE a_disposition VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE a_bill_version INT;
  DECLARE a_correction_kind VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE a_source_id UUID;
  DECLARE b_id UUID;
  DECLARE b_category TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE b_item_id TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE b_quantity TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE b_unit TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE b_tariff_version_id UUID;
  DECLARE b_order_id UUID;
  DECLARE b_round_id UUID;
  DECLARE b_created_at DATETIME(6);
  DECLARE policy LONGTEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;
  SELECT id, status, bill_revision, hospital_id, admitting_doctor_id INTO e_id, e_status, e_bill_revision, e_hospital_id, e_admitting_doctor_id FROM admissions WHERE id = NEW.admission_id FOR UPDATE;
  SELECT role INTO staff_role FROM staff_user WHERE id = NEW.actor_id AND NOT COALESCE(banned, 0);
  IF NEW.correction_exception_id IS NOT NULL THEN
    SELECT admission_id, type, disposition, CAST(JSON_VALUE(snapshot, '$.billVersion') AS SIGNED), correction_kind, source_id INTO a_admission_id, a_type, a_disposition, a_bill_version, a_correction_kind, a_source_id FROM admin_exceptions WHERE id = NEW.correction_exception_id;
    IF NOT (e_status <=> 'DISCHARGED') OR NEW.actor_type <> 'staff' OR staff_role IS NULL OR NOT (a_admission_id <=> e_id) OR NOT (a_type <=> 'POST_DISCHARGE_CORRECTION') OR NOT (a_disposition <=> 'AMEND') OR NOT (a_bill_version <=> e_bill_revision) THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Closed financial effect needs fresh exact Admin authority';
    END IF;
    SELECT id, category, item_id, quantity, unit, tariff_version_id, order_id, round_id, created_at INTO b_id, b_category, b_item_id, b_quantity, b_unit, b_tariff_version_id, b_order_id, b_round_id, b_created_at FROM care_billing_events WHERE CAST(id AS CHAR) = NEW.source_event_id AND admission_id = e_id LIMIT 1;
    IF a_correction_kind = 'CARE_BILLING' THEN
      IF NOT (b_id <=> a_source_id) OR NOT (b_category <=> NEW.category) OR NOT (b_item_id <=> NEW.item_id) OR NOT (b_quantity <=> NEW.quantity) OR NOT (b_unit <=> NEW.unit) OR NOT (b_tariff_version_id <=> NEW.tariff_version_id) OR NEW.initial_status <> 'FINAL'
         OR NOT ((b_category = 'consultation' AND staff_role = 'DOCTOR' AND e_admitting_doctor_id = NEW.actor_id AND EXISTS(SELECT 1 FROM clinical_rounds r WHERE r.id = b_round_id AND r.admission_id = e_id)) OR (b_category = 'consumable' AND staff_role = 'NURSE' AND EXISTS(SELECT 1 FROM nursing_consumables n WHERE n.id = b_id AND n.admission_id = e_id AND n.item_id = b_item_id AND n.quantity = b_quantity AND n.unit = b_unit) AND EXISTS(SELECT 1 FROM nurse_assignments n WHERE n.admission_id = e_id AND n.nurse_id = NEW.actor_id AND NOT EXISTS(SELECT 1 FROM nurse_assignment_revocations r WHERE r.assignment_id = n.id)))) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Closed care fee requires original performed source quantity pin and current proper role';
      END IF;
      IF NOT EXISTS(SELECT 1 FROM (SELECT signed_at FROM departures WHERE admission_id = e_id UNION ALL SELECT signed_at FROM exceptional_departures WHERE admission_id = e_id) d WHERE b_created_at <= d.signed_at) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Closed care pricing cannot create new retrospective clinical work';
      END IF;
    ELSEIF a_correction_kind IN ('LAB_REPORT','LAB_BILLING') THEN
      IF NOT (staff_role <=> 'LAB') OR NOT (b_order_id <=> a_source_id) OR b_category NOT IN ('lab','radiology') OR NOT EXISTS(SELECT 1 FROM lab_processing WHERE order_id = b_order_id) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Closed diagnostic fee requires original performed Lab source';
      END IF;
    ELSE
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'No authority for this closed charge';
    END IF;
    SELECT payload INTO policy FROM setting_versions WHERE id = NEW.tariff_version_id AND hospital_id = e_hospital_id;
    IF NOT (JSON_VALUE(policy, '$.type') <=> 'billable-item') OR NOT ((JSON_VALUE(policy, '$.code') COLLATE utf8mb4_nopad_bin) <=> NEW.item_id) OR NOT ((JSON_VALUE(policy, '$.category') COLLATE utf8mb4_nopad_bin) <=> NEW.category) OR NOT ((JSON_VALUE(policy, '$.unit') COLLATE utf8mb4_nopad_bin) <=> NEW.unit) OR NOT (NEW.rate_paise <=> CAST(ROUND(CAST(JSON_VALUE(policy, '$.amount') AS DECIMAL(30,6)), 0) AS SIGNED)) OR NOT (NEW.amount_paise <=> CAST(ROUND(CAST(JSON_VALUE(policy, '$.amount') AS DECIMAL(30,6)) * CAST(NEW.quantity AS DECIMAL(30,6)), 0) AS SIGNED)) THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Closed charge must retain the exact configured rate and original quantity';
    END IF;
  ELSEIF e_status = 'DISCHARGED' AND NEW.category <> 'room' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Closed non-room money requires exact source-bound amendment authority';
  END IF;
END
-- END TRIGGER

-- TRIGGER name=final_reversal_source table=charge_reversals timing=BEFORE event=INSERT pg_name=final_reversal_source
DROP TRIGGER IF EXISTS `final_reversal_source`;
CREATE TRIGGER `final_reversal_source` BEFORE INSERT ON `charge_reversals` FOR EACH ROW
trg: BEGIN
  DECLARE e_id UUID;
  DECLARE e_status VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE e_bill_revision INT;
  DECLARE e_hospital_id UUID;
  DECLARE e_admitting_doctor_id VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE staff_role VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE a_admission_id UUID;
  DECLARE a_type VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE a_disposition VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE a_bill_version INT;
  DECLARE a_correction_kind VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE a_source_id UUID;
  DECLARE b_id UUID;
  DECLARE b_category TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE b_item_id TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE b_quantity TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE b_unit TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE b_tariff_version_id UUID;
  DECLARE b_order_id UUID;
  DECLARE b_round_id UUID;
  DECLARE b_created_at DATETIME(6);
  DECLARE policy LONGTEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;
  DECLARE c_id UUID;
  DECLARE c_admission_id UUID;
  DECLARE c_source_event_id VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE c_category TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE c_amount_paise BIGINT;
  DECLARE prior BIGINT;
  DECLARE amend_id UUID;
  DECLARE amend_stay_id UUID;
  DECLARE amend_admission_id UUID;
  DECLARE amend_signed_by TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE st_id UUID;
  DECLARE st_amendment_id UUID;
  DECLARE st_started_at DATETIME(6);
  DECLARE st_ended_at DATETIME(6);
  DECLARE st_tariff_version_id UUID;
  DECLARE elapsed DECIMAL(40,6);
  DECLARE unit_ms DECIMAL(40,6);
  DECLARE rate_v DECIMAL(40,6);
  DECLARE due DECIMAL(40,6);
  DECLARE net_v DECIMAL(40,6);
  SELECT id, admission_id, source_event_id, category, amount_paise INTO c_id, c_admission_id, c_source_event_id, c_category, c_amount_paise FROM charges WHERE id = NEW.charge_id;
  SELECT id, status, bill_revision, hospital_id, admitting_doctor_id INTO e_id, e_status, e_bill_revision, e_hospital_id, e_admitting_doctor_id FROM admissions WHERE id = c_admission_id FOR UPDATE;
  SELECT role INTO staff_role FROM staff_user WHERE id = NEW.actor_id AND NOT COALESCE(banned, 0);
  SELECT COALESCE(SUM(amount_paise), 0) INTO prior FROM charge_reversals WHERE charge_id = c_id;
  IF prior + NEW.amount_paise > c_amount_paise THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Reversal exceeds remaining original source';
  END IF;
  IF c_category = 'room' OR c_source_event_id LIKE 'room:%' THEN
    SELECT id, stay_id, admission_id, signed_by INTO amend_id, amend_stay_id, amend_admission_id, amend_signed_by FROM stay_boundary_amendments WHERE id = NEW.physical_amendment_id;
    SELECT id, amendment_id, started_at, ended_at, tariff_version_id INTO st_id, st_amendment_id, st_started_at, st_ended_at, st_tariff_version_id FROM effective_room_stays WHERE id = amend_stay_id LIMIT 1;
    IF NEW.correction_exception_id IS NOT NULL OR NEW.actor_type <> 'staff' OR NOT (staff_role <=> 'ADMIN')
       OR amend_id IS NULL OR NOT (st_amendment_id <=> amend_id) OR NOT (amend_admission_id <=> e_id)
       OR NOT (amend_signed_by <=> NEW.actor_id) OR c_source_event_id NOT LIKE CONCAT('room:', st_id, ':%') THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Room reversal requires the current original-source physical amendment';
    END IF;
    SELECT payload INTO policy FROM setting_versions WHERE id = st_tariff_version_id;
    SET elapsed = GREATEST(0, COALESCE(FLOOR(UNIX_TIMESTAMP(st_ended_at) * 1000) - FLOOR(UNIX_TIMESTAMP(st_started_at) * 1000) - COALESCE(CAST(JSON_VALUE(policy, '$.graceMinutes') AS DECIMAL(30,6)), 0) * 60000, 0));
    SET unit_ms = CASE WHEN JSON_VALUE(policy, '$.basis') = 'hour' THEN 3600000 ELSE 86400000 END;
    SET rate_v = CAST(JSON_VALUE(policy, '$.amount') AS DECIMAL(30,6));
    SET due = CASE WHEN JSON_VALUE(policy, '$.rounding') = 'started-unit' THEN (CAST(FLOOR(elapsed + unit_ms - 1) AS SIGNED) DIV unit_ms) * rate_v ELSE (CAST(FLOOR(elapsed * rate_v + unit_ms / 2) AS SIGNED) DIV unit_ms) END;
    SELECT COALESCE(SUM(ch.amount_paise - COALESCE((SELECT SUM(r.amount_paise) FROM charge_reversals r WHERE r.charge_id = ch.id), 0)), 0) INTO net_v FROM charges ch WHERE ch.admission_id = e_id AND ch.source_event_id LIKE CONCAT('room:', st_id, ':%');
    IF net_v - NEW.amount_paise < due THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Physical correction cannot waive occupied time or double-credit the pinned room rate';
    END IF;
    LEAVE trg;
  END IF;
  IF NEW.physical_amendment_id IS NOT NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Physical amendment only corrects its original room source';
  END IF;
  IF NEW.correction_exception_id IS NOT NULL THEN
    SELECT admission_id, type, disposition, CAST(JSON_VALUE(snapshot, '$.billVersion') AS SIGNED), correction_kind, source_id INTO a_admission_id, a_type, a_disposition, a_bill_version, a_correction_kind, a_source_id FROM admin_exceptions WHERE id = NEW.correction_exception_id;
    IF NOT (e_status <=> 'DISCHARGED') OR NEW.actor_type <> 'staff' OR staff_role IS NULL OR NOT (a_admission_id <=> e_id) OR NOT (a_type <=> 'POST_DISCHARGE_CORRECTION') OR NOT (a_disposition <=> 'AMEND') OR NOT (a_bill_version <=> e_bill_revision) THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Closed financial effect needs fresh exact Admin authority';
    END IF;
    IF NOT (a_correction_kind <=> 'REVERSE_CHARGE') OR NOT (a_source_id <=> c_id) OR staff_role NOT IN ('ADMIN','BILLING') THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Closed reversal requires proper Billing role and original non-room charge';
    END IF;
  ELSEIF e_status = 'DISCHARGED' AND c_category <> 'room' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Closed non-room money requires exact source-bound amendment authority';
  END IF;
END
-- END TRIGGER

-- TRIGGER name=insurance_document_source table=insurance_documents timing=BEFORE event=INSERT pg_name=insurance_document_source
DROP TRIGGER IF EXISTS `insurance_document_source`;
CREATE TRIGGER `insurance_document_source` BEFORE INSERT ON `insurance_documents` FOR EACH ROW
trg: BEGIN
  DECLARE c_id UUID;
  DECLARE c_admission_id UUID;
  DECLARE e_id UUID;
  DECLARE source_case UUID;
  SELECT id, admission_id INTO c_id, c_admission_id FROM insurance_cases WHERE id = NEW.case_id;
  SELECT id INTO e_id FROM admissions WHERE id = c_admission_id FOR UPDATE;
  IF NEW.replaces_document_id IS NOT NULL THEN
    SELECT case_id INTO source_case FROM insurance_documents WHERE id = NEW.replaces_document_id;
    IF NOT (source_case <=> c_id) THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Document replacement requires same case';
    END IF;
  END IF;
END
-- END TRIGGER

-- TRIGGER name=insurance_decision_source table=insurance_decisions timing=BEFORE event=INSERT pg_name=insurance_decision_source
DROP TRIGGER IF EXISTS `insurance_decision_source`;
CREATE TRIGGER `insurance_decision_source` BEFORE INSERT ON `insurance_decisions` FOR EACH ROW
trg: BEGIN
  DECLARE c_id UUID;
  DECLARE c_admission_id UUID;
  DECLARE e_id UUID;
  DECLARE source_case UUID;
  SELECT id, admission_id INTO c_id, c_admission_id FROM insurance_cases WHERE id = NEW.case_id;
  SELECT id INTO e_id FROM admissions WHERE id = c_admission_id FOR UPDATE;
  SELECT case_id INTO source_case FROM insurance_events WHERE id = NEW.policy_event_id AND kind = 'POLICY';
  IF NOT (source_case <=> c_id) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Decision requires same-case external policy evidence';
  END IF;
END
-- END TRIGGER

-- TRIGGER name=insurance_resolution_source table=insurance_transfer_resolutions timing=BEFORE event=INSERT pg_name=insurance_resolution_source
DROP TRIGGER IF EXISTS `insurance_resolution_source`;
CREATE TRIGGER `insurance_resolution_source` BEFORE INSERT ON `insurance_transfer_resolutions` FOR EACH ROW
trg: BEGIN
  DECLARE c_id UUID;
  DECLARE c_admission_id UUID;
  DECLARE e_id UUID;
  DECLARE source_case UUID;
  SELECT id, admission_id INTO c_id, c_admission_id FROM insurance_cases WHERE id = NEW.case_id;
  SELECT id INTO e_id FROM admissions WHERE id = c_admission_id FOR UPDATE;
  IF NOT EXISTS(SELECT 1 FROM transfer_insurance_tasks WHERE id = NEW.task_id AND admission_id = c_admission_id) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Transfer resolution requires same episode';
  END IF;
  IF NEW.decision_id IS NOT NULL THEN
    SELECT case_id INTO source_case FROM insurance_decisions WHERE id = NEW.decision_id;
  ELSE
    SELECT case_id INTO source_case FROM insurance_conversions WHERE id = NEW.conversion_id;
  END IF;
  IF NOT (source_case <=> c_id) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Transfer resolution requires same-case evidence';
  END IF;
END
-- END TRIGGER

-- TRIGGER name=lab_disposition_source table=lab_dispositions timing=BEFORE event=INSERT pg_name=lab_disposition_source
DROP TRIGGER IF EXISTS `lab_disposition_source`;
CREATE TRIGGER `lab_disposition_source` BEFORE INSERT ON `lab_dispositions` FOR EACH ROW
trg: BEGIN
  DECLARE o_id UUID;
  DECLARE o_admission_id UUID;
  DECLARE o_kind TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE e_id UUID;
  DECLARE c_id UUID;
  DECLARE c_initial_status TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE c_amount_paise BIGINT;
  DECLARE r_id UUID;
  DECLARE r_charge_id UUID;
  DECLARE r_amount_paise BIGINT;
  SELECT id, admission_id, kind INTO o_id, o_admission_id, o_kind FROM clinical_orders WHERE id = NEW.order_id;
  SELECT id INTO e_id FROM admissions WHERE id = o_admission_id FOR UPDATE;
  IF o_kind NOT IN ('LAB','RADIOLOGY') OR o_admission_id <> NEW.admission_id OR NOT EXISTS(SELECT 1 FROM clinical_task_events WHERE id = NEW.stop_event_id AND order_id = o_id AND status = 'STOPPED') THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Disposition requires actual stopped diagnostic source';
  END IF;
  IF EXISTS(SELECT 1 FROM lab_samples WHERE order_id = o_id) OR EXISTS(SELECT 1 FROM lab_processing WHERE order_id = o_id) OR EXISTS(SELECT 1 FROM lab_reports WHERE order_id = o_id) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Performed diagnostic work cannot be cancelled as unperformed';
  END IF;
  SELECT ch.id, ch.initial_status, ch.amount_paise INTO c_id, c_initial_status, c_amount_paise FROM charges ch JOIN care_billing_events b ON CAST(b.id AS CHAR) = ch.source_event_id WHERE b.order_id = o_id LIMIT 1;
  IF c_id IS NOT NULL THEN
    IF c_initial_status <> 'PENDING' OR EXISTS(SELECT 1 FROM charge_finalizations WHERE charge_id = c_id) THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Only original pending source can receive unperformed disposition';
    END IF;
    IF c_amount_paise > 0 THEN
      SELECT id, charge_id, amount_paise INTO r_id, r_charge_id, r_amount_paise FROM charge_reversals WHERE id = NEW.reversal_id;
      IF r_id IS NULL OR r_charge_id <> c_id OR r_amount_paise <> c_amount_paise OR (SELECT COALESCE(SUM(amount_paise), 0) FROM charge_reversals WHERE charge_id = c_id) <> c_amount_paise THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Disposition must reverse the exact original source amount';
      END IF;
    ELSEIF NEW.reversal_id IS NOT NULL THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Zero-price source needs no fake reversal';
    END IF;
  ELSEIF NEW.reversal_id IS NOT NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Disposition cannot reverse a missing source';
  END IF;
END
-- END TRIGGER

-- TRIGGER name=lab_samples_source table=lab_samples timing=BEFORE event=INSERT pg_name=lab_samples_source
DROP TRIGGER IF EXISTS `lab_samples_source`;
CREATE TRIGGER `lab_samples_source` BEFORE INSERT ON `lab_samples` FOR EACH ROW
trg: BEGIN
  DECLARE o_id UUID;
  DECLARE o_admission_id UUID;
  DECLARE o_kind TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE e_patient_id UUID;
  DECLARE s_id UUID;
  DECLARE p_id UUID;
  DECLARE p_sample_id UUID;
  DECLARE e_id UUID;
  SELECT id, admission_id, kind INTO o_id, o_admission_id, o_kind FROM clinical_orders WHERE id = NEW.order_id;
  SELECT id, patient_id INTO e_id, e_patient_id FROM admissions WHERE id = o_admission_id FOR UPDATE;
  IF o_kind NOT IN ('LAB','RADIOLOGY') OR NEW.admission_id <> o_admission_id THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Diagnostic order/episode mismatch';
  END IF;
  IF o_kind <> 'LAB' OR NEW.patient_id <> e_patient_id OR EXISTS(SELECT 1 FROM clinical_task_events WHERE order_id = o_id AND status = 'STOPPED') THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Sample patient/order mismatch or stopped source';
  END IF;
  IF EXISTS(SELECT 1 FROM lab_dispositions WHERE order_id = o_id) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Unperformed diagnostic order was disposed';
  END IF;
END
-- END TRIGGER

-- TRIGGER name=lab_processing_source table=lab_processing timing=BEFORE event=INSERT pg_name=lab_processing_source
DROP TRIGGER IF EXISTS `lab_processing_source`;
CREATE TRIGGER `lab_processing_source` BEFORE INSERT ON `lab_processing` FOR EACH ROW
trg: BEGIN
  DECLARE o_id UUID;
  DECLARE o_admission_id UUID;
  DECLARE o_kind TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_nopad_bin;
  DECLARE e_patient_id UUID;
  DECLARE s_id UUID;
  DECLARE p_id UUID;
  DECLARE p_sample_id UUID;
  DECLARE e_id UUID;
  SELECT id, admission_id, kind INTO o_id, o_admission_id, o_kind FROM clinical_orders WHERE id = NEW.order_id;
  SELECT id, patient_id INTO e_id, e_patient_id FROM admissions WHERE id = o_admission_id FOR UPDATE;
  IF o_kind NOT IN ('LAB','RADIOLOGY') OR NEW.admission_id <> o_admission_id THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Diagnostic order/episode mismatch';
  END IF;
  SELECT id INTO s_id FROM lab_samples WHERE order_id = o_id LIMIT 1;
  IF (o_kind = 'LAB' AND (s_id IS NULL OR NOT (NEW.sample_id <=> s_id))) OR (o_kind = 'RADIOLOGY' AND NEW.sample_id IS NOT NULL) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Diagnostic sample binding mismatch';
  END IF;
  IF EXISTS(SELECT 1 FROM clinical_task_events WHERE order_id = o_id AND status = 'STOPPED') THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Doctor-stopped work cannot begin processing';
  END IF;
  IF EXISTS(SELECT 1 FROM lab_dispositions WHERE order_id = o_id) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Unperformed diagnostic order was disposed';
  END IF;
END
-- END TRIGGER

